scripts.入口守卫对话.txt:
Say("入口守卫：杨公子。");
Say("杨影枫：这塔外面看来甚是雄伟，令我不由进来逛逛。", 2);
Say("入口守卫：此处重地，杨公子请回。");
Say("杨影枫：我也不可以进去么？", 2);
Say("入口守卫：堡主有令，非堡主亲许，不可入内。杨公子请回。");
Say("杨影枫：月姑娘已经跟我说了，我可以进去。", 2);
Say("入口守卫：堡主有令，要堡主亲自跟我们说了才行。杨公子请回。");
Say("杨影枫：（他们如此阻挠我进去，莫非里面有蹊跷。）", 2);
Say("杨影枫：如果我非要进去呢？", 2);
Say("入口守卫：那小的只好得罪了。杨公子还是请回吧。");
Say("杨影枫：（莫非真儿就被关在里面？要是这样的话，此时就非得进去不可了，要不回头月眉儿也定会想我起了疑心。）", 2);
Say("杨影枫：我倒要看看你们如何拦我！", 2);
SetNpcRelation("入口守卫", 1);
SetMapTrap(10, "");
Memo("进入通天塔，查探一下。");
PlayMusic("Mc020.mp3");
Return;

